import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import { petArt } from '../common/art';
import { petState, t, STAGES } from './utils/store';
import { careButtons, face, growthBar, moodLine, profile, scene } from './components/parts';

/*
 * The lazy chunk: the art, the card's insides and the page. forum.js asks
 * for it once the browser is idle after the page is drawn.
 */

export let PageStructure;
export let IndexSidebar;
export async function loadCore() {
  if (PageStructure) return;
  const [structure, sidebar] = await Promise.all([flarum.reg.asyncModuleImport('flarum/forum/components/PageStructure'), flarum.reg.asyncModuleImport('flarum/forum/components/IndexSidebar')]);
  PageStructure = structure.default || structure;
  IndexSidebar = sidebar.default || sidebar;
}
export { default as PetPage } from './components/PetPage';

/** The card in the sidebar and in the corner's pop-up. */
export function panel(variant) {
  const s = petState();
  if (!s) return null;
  const shown = (s.list || []).slice(0, 6);
  const more = Math.max(0, s.caretakers - shown.length);
  return m("div", {
    className: `PetCard PetCard--${variant}`
  }, scene(s, {
    href: app.route('forumPet')
  }), m("div", {
    className: "PetCard-body"
  }, m("div", {
    className: "PetCard-head"
  }, m(Link, {
    className: "PetCard-name",
    href: app.route('forumPet')
  }, s.name), m("span", {
    className: `PetChip PetChip--${STAGES[s.stage]}`
  }, t(`stage.${STAGES[s.stage]}`))), m("p", {
    className: "PetCard-mood"
  }, moodLine(s)), growthBar(s), careButtons(s), s.caretakers ? m("div", {
    className: "PetCard-carers"
  }, m("span", {
    className: "PetFaces"
  }, shown.map(p => m(Link, {
    href: profile(p),
    title: p.name,
    className: "PetFaces-one"
  }, face(p))), more ? m("span", {
    className: "PetFaces-more"
  }, "+", more) : null), m("span", {
    className: "PetCard-carersText"
  }, t('carers.today', {
    count: s.caretakers
  }))) : m("p", {
    className: "PetCard-carersText PetCard-carersText--none"
  }, t('carers.none', {
    pet: s.name
  }))));
}

/** The corner button's little pet. */
export function mini() {
  const s = petState();
  if (!s) return null;
  return petArt({
    species: s.species,
    skin: s.skin,
    stage: s.stage,
    mood: s.mood,
    hat: s.hat,
    art: s.art
  });
}